"""Base class for report sections."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional
from pathlib import Path
import matplotlib.pyplot as plt
from matplotlib.figure import Figure


@dataclass
class Takeaway:
    """A single takeaway/insight from a report section."""
    text: str
    metric: Optional[str] = None
    value: Optional[float] = None
    percentile: Optional[float] = None
    is_positive: bool = True


@dataclass
class SectionContent:
    """Content generated by a report section."""
    title: str
    figures: List[Figure] = field(default_factory=list)
    figure_captions: List[str] = field(default_factory=list)
    takeaways: List[Takeaway] = field(default_factory=list)
    tables: List[Dict[str, Any]] = field(default_factory=list)
    table_titles: List[str] = field(default_factory=list)
    raw_data: Dict[str, Any] = field(default_factory=dict)

    def add_figure(self, fig: Figure, caption: str) -> None:
        """Add a figure with caption."""
        self.figures.append(fig)
        self.figure_captions.append(caption)

    def add_takeaway(self, text: str, metric: str = None, value: float = None,
                     percentile: float = None, is_positive: bool = True) -> None:
        """Add a takeaway insight."""
        self.takeaways.append(Takeaway(
            text=text,
            metric=metric,
            value=value,
            percentile=percentile,
            is_positive=is_positive
        ))

    def add_table(self, data: Dict[str, Any], title: str) -> None:
        """Add a data table."""
        self.tables.append(data)
        self.table_titles.append(title)


class BaseSection(ABC):
    """Base class for all report sections."""

    def __init__(self, player_data: Any, metrics_result: Any,
                 cohort_summary: Any, config: Dict[str, Any]):
        """
        Initialize section.

        Args:
            player_data: PlayerData object with all player information
            metrics_result: MetricsResult with calculated metrics
            cohort_summary: CohortSummary with percentile rankings
            config: Configuration dictionary
        """
        self.player_data = player_data
        self.metrics = metrics_result
        self.cohort = cohort_summary
        self.config = config

        # Color scheme
        self.colors = {
            'primary': '#1a1a2e',
            'secondary': '#16213e',
            'accent': '#0f3460',
            'highlight': '#e94560',
            'positive': '#4ade80',
            'negative': '#f87171',
            'neutral': '#94a3b8',
            'text': '#f1f5f9',
            'text_secondary': '#94a3b8',
        }

    @property
    @abstractmethod
    def section_title(self) -> str:
        """Return the section title."""
        pass

    @abstractmethod
    def generate(self) -> SectionContent:
        """Generate the section content."""
        pass

    def _get_metric_value(self, metric_name: str, default: float = 0.0) -> float:
        """Get a metric value safely."""
        if hasattr(self.metrics, 'metrics') and metric_name in self.metrics.metrics:
            return self.metrics.metrics[metric_name].value
        return default

    def _get_percentile(self, metric_name: str, default: float = 50.0) -> float:
        """Get percentile for a metric safely."""
        if hasattr(self.cohort, 'percentiles') and metric_name in self.cohort.percentiles:
            return self.cohort.percentiles[metric_name].percentile
        return default

    def _format_value(self, value: float, metric_name: str = None) -> str:
        """Format a metric value for display."""
        if metric_name and 'rate' in metric_name.lower():
            return f"{value:.1f}%"
        elif metric_name and 'accuracy' in metric_name.lower():
            return f"{value:.1f}%"
        elif value >= 100:
            return f"{value:.0f}"
        elif value >= 10:
            return f"{value:.1f}"
        else:
            return f"{value:.2f}"

    def _percentile_descriptor(self, percentile: float) -> str:
        """Get a text descriptor for a percentile."""
        if percentile >= 90:
            return "elite"
        elif percentile >= 75:
            return "excellent"
        elif percentile >= 60:
            return "above average"
        elif percentile >= 40:
            return "average"
        elif percentile >= 25:
            return "below average"
        else:
            return "poor"

    def _generate_insight(self, metric_name: str, display_name: str,
                          higher_is_better: bool = True) -> Optional[Takeaway]:
        """Generate an insight for a metric if it's noteworthy."""
        value = self._get_metric_value(metric_name)
        percentile = self._get_percentile(metric_name)

        # Only generate insight if percentile is notable (top/bottom 25%)
        if 25 <= percentile <= 75:
            return None

        descriptor = self._percentile_descriptor(percentile)
        formatted_value = self._format_value(value, metric_name)

        is_positive = (percentile >= 50) if higher_is_better else (percentile <= 50)

        if percentile >= 75:
            text = f"{descriptor.capitalize()} {display_name.lower()}: {formatted_value} per 90 ({percentile:.0f}th percentile)"
        elif percentile <= 25:
            text = f"{descriptor.capitalize()} {display_name.lower()}: {formatted_value} per 90 ({percentile:.0f}th percentile)"
        else:
            return None

        return Takeaway(
            text=text,
            metric=metric_name,
            value=value,
            percentile=percentile,
            is_positive=is_positive
        )

    def _close_figures(self, content: SectionContent) -> None:
        """Close all matplotlib figures to free memory."""
        for fig in content.figures:
            plt.close(fig)
